define(["core/ajax"],function(Ajax){const init=function(flexbookId){document.querySelectorAll(".flexbook-content-disclosure details").forEach(function(details){details.addEventListener("toggle",function(){if(!details.open){return}const block=details.closest(".flexbook-content");Ajax.call([{methodname:"mod_flexbook_mark_content_completed",args:{flexbookid:flexbookId,contentid:Number(block.dataset.contentId),metric:100,details:JSON.stringify({visited:[0]})}}])[0].catch(function(){})})})};return{init:init}});